\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Dark Exhibition Theme ──
\definecolor{primary}{HTML}{0F172A}       % deep navy background
\definecolor{secondary}{HTML}{1E293B}     % slightly lighter navy for cards
\definecolor{tertiary}{HTML}{334155}      % slate for borders
\definecolor{amber}{HTML}{F59E0B}         % warm amber — progress/hope
\definecolor{gold}{HTML}{FBBF24}          % gold accent
\definecolor{urgred}{HTML}{EF4444}        % urgent red
\definecolor{darkred}{HTML}{DC2626}       % deeper red
\definecolor{teal}{HTML}{2DD4BF}          % teal for positive trends
\definecolor{textwhite}{HTML}{F1F5F9}     % off-white text
\definecolor{textmuted}{HTML}{94A3B8}     % muted slate text
\definecolor{cardbg}{HTML}{1E293B}        % card background
\definecolor{cardheader}{HTML}{0F172A}    % card header background
\definecolor{statbg}{HTML}{1A1028}        % stat banner background (deep purple-navy)
\definecolor{herobg}{HTML}{450A0A}        % hero stat background (dark red)

\pagecolor{primary}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{amber}$\blacktriangleright$}}

% ── Figure macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[2mm]
  {\fontsize{20}{26}\selectfont\color{textmuted}\textit{#3}}\vspace{2mm}%
}

% ── Card styles for dark theme ──
\tcbset{
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary,
    borderline west={5pt}{0pt}{amber},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={amber!40},
    valign=top, colupper=textwhite,
    drop shadow={opacity=0.3, shadow xshift=2pt, shadow yshift=-2pt},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary,
    borderline west={5pt}{0pt}{teal},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={teal!40},
    valign=top, colupper=textwhite,
    drop shadow={opacity=0.3, shadow xshift=2pt, shadow yshift=-2pt},
  },
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary,
    borderline west={5pt}{0pt}{urgred},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{urgred},
    coltitle=urgred, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={urgred!40},
    valign=top, colupper=textwhite,
    drop shadow={opacity=0.3, shadow xshift=2pt, shadow yshift=-2pt},
  },
  herocard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=herobg,
    borderline west={6pt}{0pt}{urgred},
    borderline east={6pt}{0pt}{urgred},
    left=14pt, right=14pt, top=8pt, bottom=8pt,
    valign=center, colupper=textwhite,
    drop shadow={opacity=0.4, shadow xshift=2pt, shadow yshift=-3pt},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=2mm},
]

% ══════════════════════════════════════════════════════════
% TITLE BAR — rows 1–3
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  borderline south={3pt}{0pt}{amber!60},
  left=30pt, right=30pt, top=20pt, bottom=12pt,
  halign=center, valign=center,
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{22}{28}\selectfont\color{amber}\textbf{A PREVENTABLE CRISIS}\quad$\vert$\quad\textbf{A STORY OF PROGRESS}}\\[14pt]
  {\fontsize{60}{72}\selectfont\bfseries\color{textwhite} MALARIA}\\[4pt]
  {\fontsize{34}{42}\selectfont\color{textmuted} Global Burden \& the Road Ahead}
}

% ══════════════════════════════════════════════════════════
% HERO STAT — rows 3–6 (most visually dominant element)
% ══════════════════════════════════════════════════════════
\posterbox[herocard
]{name=hero, column=1, span=2, between=row3 and row6}{
  \centering
  {\fontsize{20}{26}\selectfont\color{urgred!70}\textbf{EVERY SINGLE DAY}}\\[8pt]
  {\fontsize{100}{110}\selectfont\bfseries\color{urgred} 1{,}320}\\[2pt]
  {\fontsize{36}{44}\selectfont\bfseries\color{textwhite} CHILDREN DIE FROM MALARIA}\\[10pt]
  {\fontsize{22}{28}\selectfont\color{textmuted} A preventable, treatable disease that still claims more than}\\[2pt]
  {\fontsize{28}{36}\selectfont\bfseries\color{amber} 500{,}000+ lives every year}\\[4pt]
  {\fontsize{20}{26}\selectfont\color{textmuted} The vast majority are children under 5, in Sub-Saharan Africa}
}

% ══════════════════════════════════════════════════════════
% STAT BANNER — rows 6–7
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!90!black, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={2pt}{0pt}{tertiary},
]{name=stats, column=1, span=2, between=row6 and row7}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \colorbox{secondary}{\parbox{0.90\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{40}{48}\selectfont\bfseries\color{urgred} >500K}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textmuted} deaths per year (2010s)}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \colorbox{secondary}{\parbox{0.90\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{40}{48}\selectfont\bfseries\color{amber} 50\% $\to$ 27\%}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textmuted} land area with malaria risk}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \colorbox{secondary}{\parbox{0.90\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{40}{48}\selectfont\bfseries\color{teal} Africa}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textmuted} bears the greatest burden}\vspace{6pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════
% LEFT COLUMN
% ══════════════════════════════════════════════════════════

% ── What Is Malaria? — rows 7–9 ──
\posterbox[ambercard, title={What Is Malaria?}
]{name=whatisit, column=1, between=row7 and row9}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item Caused by \textit{Plasmodium} parasites, spread by mosquito bites
    \item Invades red blood cells $\to$ fevers, chills, organ failure
    \item \textit{P.~falciparum} is the deadliest species
    \item Preventable and treatable with existing tools
  \end{itemize}
}

% ── From Half the World to a Quarter — rows 9–13 ──
\posterbox[tealcard, title={From Half the World to a Quarter}
]{name=historical, column=1, between=row9 and row13}{
  \fontsize{24}{32}\selectfont
  Malaria is \textbf{not inherently tropical}. It once covered roughly half the world's land --- including Europe and North America.\\[8pt]
  \posterfig{0.96}{figures/land_coverage.png}{Global malaria-endemic land area: dramatic contraction over a century.}
  \vspace{4pt}
  \colorbox{primary}{\parbox{0.94\linewidth}{\centering\vspace{4pt}%
    {\fontsize{20}{26}\selectfont\color{textmuted} Even Abraham Lincoln and Oliver Cromwell contracted malaria}\vspace{4pt}%
  }}
}

% ── What Drove Elimination? — rows 13–16 ──
\posterbox[ambercard, title={What Drove Elimination?}
]{name=drivers, column=1, between=row13 and row16}{
  \fontsize{24}{32}\selectfont
  Three forces shrank malaria from wealthy regions:\\[6pt]
  \colorbox{primary}{\parbox{0.93\linewidth}{\vspace{4pt}%
    {\color{amber}\bfseries\fontsize{22}{28}\selectfont 1.\enspace Public Health Measures}\\
    {\fontsize{22}{28}\selectfont\color{textwhite} Widespread insecticides targeting mosquitoes}\vspace{4pt}%
  }}\\[6pt]
  \colorbox{primary}{\parbox{0.93\linewidth}{\vspace{4pt}%
    {\color{amber}\bfseries\fontsize{22}{28}\selectfont 2.\enspace Land Use Change}\\
    {\fontsize{22}{28}\selectfont\color{textwhite} Draining swampland reduced breeding grounds}\vspace{4pt}%
  }}\\[6pt]
  \colorbox{primary}{\parbox{0.93\linewidth}{\vspace{4pt}%
    {\color{amber}\bfseries\fontsize{22}{28}\selectfont 3.\enspace Socioeconomic Development}\\
    {\fontsize{22}{28}\selectfont\color{textwhite} Better housing, nets, and treatment access}\vspace{4pt}%
  }}
}

% ── Call to Action (left-bottom) — rows 16–20 ──
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=herobg!80!primary,
  borderline west={6pt}{0pt}{urgred},
  left=14pt, right=14pt, top=12pt, bottom=12pt,
  valign=center, colupper=textwhite,
  drop shadow={opacity=0.3},
]{name=cta, column=1, between=row16 and row20}{
  \centering
  {\fontsize{26}{34}\selectfont\color{urgred}\bfseries THE URGENCY}\\[12pt]
  {\fontsize{22}{30}\selectfont\color{textwhite}
    Every day that passes without action,\\[4pt]
    approximately \textbf{\color{urgred}1{,}320 children} lose their lives\\[4pt]
    to a disease we \textbf{know how to prevent and treat}.\\[14pt]
    The world has already proven that\\[4pt]
    \textbf{\color{amber}elimination is possible} ---\\[4pt]
    the challenge is extending that success\\[4pt]
    to the regions that need it most.%
  }\\[14pt]
  \colorbox{amber!20!primary}{\parbox{0.80\linewidth}{\centering\vspace{6pt}%
    {\fontsize{20}{26}\selectfont\color{amber}\bfseries Insecticide-treated bednets remain one of the}\\
    {\fontsize{20}{26}\selectfont\color{amber}\bfseries most cost-effective health interventions on Earth}\vspace{6pt}%
  }}
}

% ══════════════════════════════════════════════════════════
% RIGHT COLUMN
% ══════════════════════════════════════════════════════════

% ── The Burden — rows 7–10 ──
\posterbox[redcard, title={The Burden: Who Malaria Kills}
]{name=burden, column=2, between=row7 and row10}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item \textbf{\color{urgred}Children under 5} account for the largest share of deaths
    \item \textbf{\color{urgred}Sub-Saharan Africa} bears the overwhelming majority
    \item Most deaths caused by \textit{Plasmodium falciparum}
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary}{\parbox{0.93\linewidth}{\vspace{6pt}%
    \centering
    {\fontsize{48}{56}\selectfont\bfseries\color{urgred} 500{,}000+}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textmuted} people died annually during the 2010s}\\[2pt]
    {\fontsize{20}{26}\selectfont\color{textmuted} The vast majority were young children in Africa}\vspace{6pt}%
  }}
}

% ── Death Trends Chart — rows 10–16 ──
\posterbox[tealcard, title={Death Toll Trends: 2000--2023}
]{name=trends, column=2, between=row10 and row16}{
  \fontsize{24}{32}\selectfont
  \posterfig{0.98}{figures/death_trends.png}{WHO estimates show steady decline 2000--2015, stalled progress, and COVID-19 setback in 2020.}
  \vspace{4pt}
  \colorbox{primary}{\parbox{0.93\linewidth}{\vspace{4pt}%
    {\fontsize{20}{26}\selectfont\color{teal}$\blacktriangleright$\enspace \textbf{2000--2015:} Steady decline --- global investment worked}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textmuted}$\blacktriangleright$\enspace \textbf{2015--2019:} Progress stalled --- funding plateaued}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{urgred}$\blacktriangleright$\enspace \textbf{2020:} Sharp rise --- COVID disrupted health services}\vspace{4pt}%
  }}
}

% ── What Works — rows 16–20 ──
\posterbox[ambercard, title={What Works: Tools to Beat Malaria}
]{name=interventions, column=2, between=row16 and row20}{
  \fontsize{24}{32}\selectfont
  The same interventions that eliminated malaria from wealthy regions can be scaled:\\[8pt]
  \posterfig{0.96}{figures/interventions.png}{Three proven strategies for continued progress against malaria.}
  \vspace{4pt}
  \colorbox{primary}{\parbox{0.93\linewidth}{\vspace{6pt}%
    \centering
    {\fontsize{22}{28}\selectfont\color{amber}\bfseries New malaria vaccines offer a promising}\\
    {\fontsize{22}{28}\selectfont\color{amber}\bfseries additional layer of protection for children}\vspace{6pt}%
  }}
}

\end{tcbposter}
\end{document}
LATEXEOF
