\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Dark Exhibition Theme ──
\definecolor{primary}{HTML}{0F172A}       % deep navy background
\definecolor{secondary}{HTML}{1E293B}     % slightly lighter navy for cards
\definecolor{tertiary}{HTML}{334155}      % slate for borders
\definecolor{amber}{HTML}{F59E0B}         % warm amber — progress/hope
\definecolor{gold}{HTML}{FBBF24}          % gold accent
\definecolor{urgred}{HTML}{EF4444}        % urgent red
\definecolor{darkred}{HTML}{DC2626}       % deeper red
\definecolor{teal}{HTML}{2DD4BF}          % teal for positive trends
\definecolor{textwhite}{HTML}{F1F5F9}     % off-white text
\definecolor{textmuted}{HTML}{94A3B8}     % muted slate text
\definecolor{cardbg}{HTML}{1E293B}        % card background
\definecolor{cardheader}{HTML}{0F172A}    % card header background
\definecolor{statbg}{HTML}{1A1028}        % stat banner background (deep purple-navy)
\definecolor{herobg}{HTML}{450A0A}        % hero stat background (dark red)

\pagecolor{primary}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{amber}$\blacktriangleright$}}

% ── Figure macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[2mm]
  {\fontsize{20}{26}\selectfont\color{textmuted}\textit{#3}}\vspace{2mm}%
}

% ── Card styles for dark theme ──
\tcbset{
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary,
    borderline west={5pt}{0pt}{amber},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={amber!40},
    valign=top, colupper=textwhite,
    drop shadow={opacity=0.3},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary,
    borderline west={5pt}{0pt}{teal},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={teal!40},
    valign=top, colupper=textwhite,
    drop shadow={opacity=0.3},
  },
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary,
    borderline west={5pt}{0pt}{urgred},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{urgred},
    coltitle=urgred, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={urgred!40},
    valign=top, colupper=textwhite,
    drop shadow={opacity=0.3},
  },
  herocard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=herobg,
    borderline west={6pt}{0pt}{urgred},
    borderline east={6pt}{0pt}{urgred},
    left=14pt, right=14pt, top=8pt, bottom=8pt,
    valign=center, colupper=textwhite,
    drop shadow={opacity=0.4},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=2mm},
]

% ══════════════════════════════════════════════════════════
% TITLE BAR — rows 1–3
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  borderline south={3pt}{0pt}{amber!60},
  left=30pt, right=30pt, top=20pt, bottom=12pt,
  halign=center, valign=center,
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{22}{28}\selectfont\color{amber}\textbf{A PREVENTABLE CRISIS}\quad$\vert$\quad\textbf{A STORY OF PROGRESS}}\\[14pt]
  {\fontsize{60}{72}\selectfont\bfseries\color{textwhite} MALARIA}\\[4pt]
  {\fontsize{34}{42}\selectfont\color{textmuted} Global Burden \& the Road Ahead}
}

% ══════════════════════════════════════════════════════════
% HERO STAT — rows 3–6 (most visually dominant element)
% ══════════════════════════════════════════════════════════
\posterbox[herocard
]{name=hero, column=1, span=2, between=row3 and row6}{
  \centering
