\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Dark Exhibition Theme ──
\definecolor{primary}{HTML}{0F172A}
\definecolor{secondary}{HTML}{1E293B}
\definecolor{tertiary}{HTML}{334155}
\definecolor{amber}{HTML}{F59E0B}
\definecolor{gold}{HTML}{FBBF24}
\definecolor{urgred}{HTML}{EF4444}
\definecolor{darkred}{HTML}{DC2626}
\definecolor{teal}{HTML}{2DD4BF}
\definecolor{textwhite}{HTML}{F1F5F9}
\definecolor{textmuted}{HTML}{94A3B8}
\definecolor{herobg}{HTML}{450A0A}

\pagecolor{primary}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{amber}$\blacktriangleright$}}

% ── Figure macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[2mm]
  {\fontsize{20}{26}\selectfont\color{textmuted}\textit{#3}}\vspace{2mm}%
}

% ── Card styles for dark theme ──
\tcbset{
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary,
    borderline west={5pt}{0pt}{amber},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={amber!40},
    valign=top, colupper=textwhite,
    drop shadow={opacity=0.3},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary,
    borderline west={5pt}{0pt}{teal},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{teal},
    coltitle=teal, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={teal!40},
    valign=top, colupper=textwhite,
    drop shadow={opacity=0.3},
  },
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=secondary,
    borderline west={5pt}{0pt}{urgred},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{urgred},
    coltitle=urgred, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={urgred!40},
    valign=top, colupper=textwhite,
    drop shadow={opacity=0.3},
  },
  herocard/.style={
    enhanced, arc=0pt, boxrule=0pt,
    colback=herobg,
    borderline west={6pt}{0pt}{urgred},
    borderline east={6pt}{0pt}{urgred},
    left=14pt, right=14pt, top=8pt, bottom=8pt,
    valign=center, colupper=textwhite,
    drop shadow={opacity=0.4},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=2mm},
]

% ══════════════════════════════════════════════════════════
% TITLE BAR — rows 1–2
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  borderline south={3pt}{0pt}{amber!60},
  left=30pt, right=30pt, top=16pt, bottom=8pt,
  halign=center, valign=center,
]{name=title, column=1, span=2, between=top and row2}{
  {\fontsize{20}{26}\selectfont\color{amber}\textbf{A PREVENTABLE CRISIS}\quad$\vert$\quad\textbf{A STORY OF PROGRESS}}\\[10pt]
  {\fontsize{56}{68}\selectfont\bfseries\color{textwhite} MALARIA}\\[4pt]
  {\fontsize{28}{36}\selectfont\color{textmuted} Global Burden \& the Road Ahead}
}

% ══════════════════════════════════════════════════════════
% HERO STAT — rows 2–5 (most visually dominant element)
% ══════════════════════════════════════════════════════════
\posterbox[herocard
]{name=hero, column=1, span=2, between=row2 and row5}{
  \centering
  {\fontsize{24}{30}\selectfont\color{urgred!80}\textbf{EVERY SINGLE DAY}}\\[10pt]
  {\fontsize{120}{130}\selectfont\bfseries\color{urgred} 1{,}320}\\[4pt]
  {\fontsize{40}{50}\selectfont\bfseries\color{textwhite} CHILDREN DIE FROM MALARIA}\\[12pt]
  {\fontsize{24}{30}\selectfont\color{textmuted} A preventable, treatable disease that still claims more than}\\[4pt]
  {\fontsize{32}{40}\selectfont\bfseries\color{amber} 500{,}000+ lives every year}\\[6pt]
  {\fontsize{22}{28}\selectfont\color{textmuted} The vast majority are children under 5 in Sub-Saharan Africa}
}

% ══════════════════════════════════════════════════════════
% STAT BANNER — rows 5–6
% ══════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!90!black, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={2pt}{0pt}{tertiary},
]{name=stats, column=1, span=2, between=row5 and row6}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \colorbox{secondary}{\parbox{0.90\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{44}{52}\selectfont\bfseries\color{urgred} >500K}\\[4pt]
      {\fontsize{20}{26}\selectfont\color{textmuted} deaths per year (2010s)}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \colorbox{secondary}{\parbox{0.90\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{44}{52}\selectfont\bfseries\color{amber} 50\%\,$\to$\,27\%}\\[4pt]
      {\fontsize{20}{26}\selectfont\color{textmuted} land area with malaria}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \colorbox{secondary}{\parbox{0.90\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{44}{52}\selectfont\bfseries\color{teal} Africa}\\[4pt]
      {\fontsize{20}{26}\selectfont\color{textmuted} bears the greatest burden}\vspace{6pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════
% LEFT COLUMN
% ══════════════════════════════════════════════════════════

% ── What Is Malaria? — rows 6–8 ──
\posterbox[ambercard, title={What Is Malaria?}
]{name=whatisit, column=1, between=row6 and row8}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item Caused by \textit{Plasmodium} parasites, spread by mosquitoes
    \item Invades red blood cells $\to$ fevers, chills, organ failure
    \item \textit{P.~falciparum} is the deadliest species
    \item Preventable and treatable with existing tools
  \end{itemize}
}

% ── From Half the World to a Quarter — rows 8–13 ──
\posterbox[tealcard, title={From Half the World to a Quarter}
]{name=historical, column=1, between=row8 and row13}{
  \fontsize{24}{32}\selectfont
  Malaria is \textbf{not inherently tropical}. It once covered roughly half the world --- including Europe and North America.\\[8pt]
  \posterfig{0.96}{figures/land_coverage.png}{Malaria-endemic land area shrank dramatically over a century.}
  \vspace{2pt}
  \colorbox{primary}{\parbox{0.94\linewidth}{\centering\vspace{4pt}%
    {\fontsize{20}{26}\selectfont\color{textmuted} Abraham Lincoln and Oliver Cromwell both contracted malaria}\vspace{4pt}%
  }}
}

% ── What Drove Elimination? — rows 13–16 ──
\posterbox[ambercard, title={What Drove Elimination?}
]{name=drivers, column=1, between=row13 and row16}{
  \fontsize{24}{32}\selectfont
  Three forces shrank malaria from wealthy regions:\\[6pt]
  \colorbox{primary}{\parbox{0.93\linewidth}{\vspace{4pt}%
    {\color{amber}\bfseries\fontsize{22}{28}\selectfont 1.\enspace Public Health Measures}\\
    {\fontsize{22}{28}\selectfont\color{textwhite} Widespread insecticides targeting mosquitoes}\vspace{4pt}%
  }}\\[6pt]
