    \colorbox{secondary}{\parbox{0.90\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{44}{52}\selectfont\bfseries\color{teal} Africa}\\[4pt]
      {\fontsize{20}{26}\selectfont\color{textmuted} bears the greatest burden}\vspace{6pt}%
    }}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════
% LEFT COLUMN
% ══════════════════════════════════════════════════════════

% ── What Is Malaria? — rows 6–8 ──
\posterbox[ambercard, title={What Is Malaria?}
]{name=whatisit, column=1, between=row6 and row8}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item Caused by \textit{Plasmodium} parasites, spread by mosquitoes
    \item Invades red blood cells $\to$ fevers, chills, organ failure
    \item \textit{P.~falciparum} is the deadliest species
    \item Preventable and treatable with existing tools
  \end{itemize}
}

% ── From Half the World to a Quarter — rows 8–13 ──
\posterbox[tealcard, title={From Half the World to a Quarter}
]{name=historical, column=1, between=row8 and row13}{
  \fontsize{24}{32}\selectfont
  Malaria is \textbf{not inherently tropical}. It once covered roughly half the world --- including Europe and North America.\\[8pt]
  \posterfig{0.96}{figures/land_coverage.png}{Malaria-endemic land area shrank dramatically over a century.}
  \vspace{2pt}
  \colorbox{primary}{\parbox{0.94\linewidth}{\centering\vspace{4pt}%
    {\fontsize{20}{26}\selectfont\color{textmuted} Abraham Lincoln and Oliver Cromwell both contracted malaria}\vspace{4pt}%
  }}
}

% ── What Drove Elimination? — rows 13–16 ──
\posterbox[ambercard, title={What Drove Elimination?}
]{name=drivers, column=1, between=row13 and row16}{
  \fontsize{24}{32}\selectfont
  Three forces shrank malaria from wealthy regions:\\[6pt]
  \colorbox{primary}{\parbox{0.93\linewidth}{\vspace{4pt}%
    {\color{amber}\bfseries\fontsize{22}{28}\selectfont 1.\enspace Public Health Measures}\\
    {\fontsize{22}{28}\selectfont\color{textwhite} Widespread insecticides targeting mosquitoes}\vspace{4pt}%
  }}\\[6pt]
  \colorbox{primary}{\parbox{0.93\linewidth}{\vspace{4pt}%
    {\color{amber}\bfseries\fontsize{22}{28}\selectfont 2.\enspace Land Use Change}\\
    {\fontsize{22}{28}\selectfont\color{textwhite} Draining swampland reduced breeding grounds}\vspace{4pt}%
  }}\\[6pt]
  \colorbox{primary}{\parbox{0.93\linewidth}{\vspace{4pt}%
    {\color{amber}\bfseries\fontsize{22}{28}\selectfont 3.\enspace Socioeconomic Development}\\
    {\fontsize{22}{28}\selectfont\color{textwhite} Better housing, nets, and treatment access}\vspace{4pt}%
  }}
}

% ── Call to Action — rows 16–20 ──
\posterbox[
  enhanced, arc=0pt, boxrule=0pt,
  colback=herobg!80!primary,
  borderline west={6pt}{0pt}{urgred},
  left=14pt, right=14pt, top=10pt, bottom=10pt,
  valign=center, colupper=textwhite,
  drop shadow={opacity=0.3},
]{name=cta, column=1, between=row16 and row20}{
  \centering
  {\fontsize{28}{36}\selectfont\color{urgred}\bfseries THE URGENCY}\\[14pt]
  {\fontsize{24}{32}\selectfont\color{textwhite}
    Every day that passes without action,\\[4pt]
    approximately \textbf{\color{urgred}1{,}320 children} lose their lives\\[4pt]
    to a disease we \textbf{know how to prevent and treat}.%
  }\\[14pt]
  {\fontsize{24}{32}\selectfont\color{textwhite}
    The world has already proven that\\[4pt]
    \textbf{\color{amber}elimination is possible} ---\\[4pt]
    the challenge is extending that success\\[4pt]
    to the regions that need it most.%
  }\\[14pt]
  \colorbox{amber!20!primary}{\parbox{0.82\linewidth}{\centering\vspace{6pt}%
    {\fontsize{22}{28}\selectfont\color{amber}\bfseries Insecticide-treated bednets remain one of the}\\
    {\fontsize{22}{28}\selectfont\color{amber}\bfseries most cost-effective health interventions on Earth}\vspace{6pt}%
  }}
}

% ══════════════════════════════════════════════════════════
% RIGHT COLUMN
% ══════════════════════════════════════════════════════════

% ── The Burden — rows 6–9 ──
\posterbox[redcard, title={The Burden: Who Malaria Kills}
]{name=burden, column=2, between=row6 and row9}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=6pt]
    \item \textbf{\color{urgred}Children under 5} --- the largest share of deaths
    \item \textbf{\color{urgred}Sub-Saharan Africa} --- the overwhelming majority
    \item Most deaths caused by \textit{Plasmodium falciparum}
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary}{\parbox{0.93\linewidth}{\vspace{6pt}%
    \centering
    {\fontsize{50}{60}\selectfont\bfseries\color{urgred} 500{,}000+}\\[4pt]
    {\fontsize{22}{28}\selectfont\color{textmuted} people died annually during the 2010s}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textmuted} The vast majority were young children in Africa}\vspace{6pt}%
  }}
}

% ── Death Trends Chart — rows 9–15 ──
\posterbox[tealcard, title={Death Toll Trends: 2000--2023}
]{name=trends, column=2, between=row9 and row15}{
  \fontsize{24}{32}\selectfont
  \posterfig{0.98}{figures/death_trends.png}{WHO estimates show steady decline 2000--2015, stalled progress, then COVID-19 setback in 2020.}
  \vspace{6pt}
  \colorbox{primary}{\parbox{0.93\linewidth}{\vspace{4pt}%
    {\fontsize{22}{28}\selectfont\color{teal}$\blacktriangleright$\enspace \textbf{2000--2015:} Steady decline --- investment worked}\\[4pt]
    {\fontsize{22}{28}\selectfont\color{textmuted}$\blacktriangleright$\enspace \textbf{2015--2019:} Progress stalled --- funding plateaued}\\[4pt]
    {\fontsize{22}{28}\selectfont\color{urgred}$\blacktriangleright$\enspace \textbf{2020:} Sharp rise --- COVID disrupted services}\vspace{4pt}%
  }}
}

% ── What Works — rows 15–20 ──
\posterbox[ambercard, title={What Works: Tools to Beat Malaria}
]{name=interventions, column=2, between=row15 and row20}{
  \fontsize{24}{32}\selectfont
  The same interventions that eliminated malaria from wealthy regions can be scaled worldwide:\\[8pt]
  \posterfig{0.96}{figures/interventions.png}{Three proven strategies for continued progress against malaria.}
  \vspace{4pt}
  \colorbox{primary}{\parbox{0.93\linewidth}{\vspace{6pt}%
    \centering
    {\fontsize{22}{28}\selectfont\color{amber}\bfseries New malaria vaccines offer a promising}\\
    {\fontsize{22}{28}\selectfont\color{amber}\bfseries additional layer of protection for children}\vspace{6pt}%
  }}
}

\end{tcbposter}
